import React from 'react';
import { useTranslation } from 'react-i18next';
import SectionTitle from '../../../components/SectionTitle';
import { ResumeWorkItem } from '../../../models/resume';
import { formatPeriod } from '../../../transformers/resume';
import { ResumeStyles } from '../../../themes/shared/ResumeStyles';

type WorkSectionProps = {
  work: ResumeWorkItem[];
  styles: ResumeStyles;
};

const WorkSection: React.FC<WorkSectionProps> = ({ work, styles }) => {
  const { t } = useTranslation();
  if (!work.length) {
    return null;
  }
  return (
    <section className={styles.section}>
      <SectionTitle title={t('sections.work')} subtitle={t('sections.workSubtitle')} />
      <div className={styles.sectionBody}>
        {work.map((item) => (
          <article key={`${item.company}-${item.position}`} className={styles.entryCard}>
            <div className={styles.entryHeader}>
              <div className={styles.entryHeading}>
                <span className={styles.entryTitle}>{item.company}</span>
                {item.position ? (
                  <span className={styles.entrySubtitle}> · {item.position}</span>
                ) : null}
              </div>
              <div className={styles.entryDate}>
                {formatPeriod(item.startDate, item.endDate, t('labels.present'))}
              </div>
            </div>
            {item.summary ? <p className={styles.entrySummary}>{item.summary}</p> : null}
            {item.highlights?.length ? (
              <ul className={styles.entryList}>
                {item.highlights.map((highlight) => (
                  <li key={highlight}>{highlight}</li>
                ))}
              </ul>
            ) : null}
          </article>
        ))}
      </div>
    </section>
  );
};

export default WorkSection;
